			const observer = new MutationObserver(() => {
				if (!document.body.contains(el)) {
					panels.delete(el);
					observer.disconnect();
					removalObservers.delete(el);
				}
			});
			observer.observe(el.parentElement || document.body, {
				childList: true,
				subtree: true
			});
